volatile uint32_t ms_ticks = 0;

ISR(TIMER0_COMPA_vect) {        // anropas varje millisekund (CTC-läge)
    ms_ticks++;
}

uint32_t millis(void) {
    uint32_t t;
    cli();                      // 32 bitar läses i flera steg på en 8-bitars MCU,
    t = ms_ticks;               // så stäng av avbrott så värdet inte ändras mitt i
    sei();
    return t;
}

